  ui_story_5029_50290026_13_dialog_content = "(ถ้าเราหาคนร้ายไม่เจอ ท่านเจ้าเมืองอาจตกอยู่ในอันตราย... แล้วฉันก็จะต้องติดอยู่ในนี้ตลอดไป)",
